func streamAIRequest(personID string) *http.Request {
	body, err := json.Marshal(map[string]any{"prompt": "요즘 소원해진 사람이 있나요?", "person_id": personID})
	if err != nil {
		panic(err)
	}
	req := httptest.NewRequest(http.MethodPost, "/api/v1/ai/stream", strings.NewReader(string(body)))
	return req.WithContext(context.WithValue(req.Context(), userContextKey, User{ID: "u1"}))
}

// relationshipContext는 본문 person_id를 uuid 컬럼인 p.id와 맞대므로, 모양이
// 어긋난 값이면 postgres가 22P02를 내고 ai.go의 internalError가 500으로 감싼다.
// 잘못 보낸 요청이니 400이어야 하고, 그 판단은 설정 조회보다 앞이라 store가
// nil이어도 패닉 없이 끝나야 한다.
func TestStreamAIRejectsMalformedPersonIDBeforeDB(t *testing.T) {
	cases := []struct{ name, personID string }{
		{"uuid가 아닌 문자열", "not-a-uuid"},
		{"하이픈 없는 16진수", "0e2f1c9a4b8d4e6fa1b2c3d4e5f60718"},
		{"중괄호로 감싼 형태", "{0e2f1c9a-4b8d-4e6f-a1b2-c3d4e5f60718}"},
		{"따옴표가 섞인 값", "1' OR '1'='1"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			rec, panicked := callWithoutStore((&Server{}).streamAI, streamAIRequest(tc.personID))
			if panicked {
				t.Fatalf("설정·질의까지 내려갔다 — person_id 검증이 DB 앞에서 끝나지 않는다")
			}
			if rec.Code != http.StatusBadRequest {
				t.Fatalf("상태가 %d, 400이어야 한다", rec.Code)
			}
			var out apiError
			if err := json.NewDecoder(rec.Body).Decode(&out); err != nil {
				t.Fatal(err)
			}
			if out.Error.Code != "validation_error" || out.Error.Message == "" {
				t.Fatalf("응답 본문이 다르다: %+v", out)
			}
		})
	}
}

// 정상 uuid와 빈 person_id(전체 관계 요약 경로)는 가드가 건드리지 않아야 한다.
// store가 nil이라 설정 조회(readSetting)에서 패닉이 나는 것이 곧 "가드를 지나
// 원래 가던 길로 갔다"는 증거다.
func TestStreamAILetsWellFormedPersonIDReachDB(t *testing.T) {
	cases := []struct{ name, personID string }{
		{"소문자 uuid", "0e2f1c9a-4b8d-4e6f-a1b2-c3d4e5f60718"},
		{"대문자 uuid", "0E2F1C9A-4B8D-4E6F-A1B2-C3D4E5F60718"},
		{"person_id 없음", ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			rec, panicked := callWithoutStore((&Server{}).streamAI, streamAIRequest(tc.personID))
			if !panicked {
				t.Fatalf("DB에 닿지 않고 %d로 끝났다 — 가드가 정상 id를 거부한다", rec.Code)
			}
		})
	}
}

// safeAIError는 제공자 오류를 slog로 내보내기 전에 길이를 자른다. 자르는 자리가
// 바이트 단위라 한국어(룬 3바이트) 오류가 300바이트 경계를 걸치면 마지막 룬이
// 쪼개져 꼬리가 U+FFFD로 깨진다 — 로그를 읽으려고 남기는 값이니 깨지면 안 된다.
// 반대로 300바이트 이하는 한 바이트도 손대지 않아야 한다(지금 동작 유지).
func TestSafeAIError(t *testing.T) {
	// 앞에 ASCII 한 글자를 두어 300이 룬 경계와 어긋나게 만든다. 한국어 룬은
	// 1+3k 바이트 자리에서 시작하므로 300번째 바이트는 어떤 룬의 중간이다.
	split := "x" + strings.Repeat("한", 150)
	if utf8.RuneStart(split[300]) {
		t.Fatalf("시험 입력이 300바이트에서 룬을 쪼개지 않는다 — 입력을 고쳐야 한다")
	}

	t.Run("룬을 쪼개지 않는다", func(t *testing.T) {
		got := safeAIError(errors.New(split))
		if !utf8.ValidString(got) {
			t.Fatalf("반환값이 올바른 UTF-8이 아니다: %q", got)
		}
		if strings.ContainsRune(got, utf8.RuneError) {
			t.Fatalf("반환값에 U+FFFD가 섞였다: %q", got)
		}
		if len(got) > 300 {
			t.Fatalf("길이가 %d바이트 — 300바이트를 넘는다", len(got))
		}
		// 자르기 전 온전한 룬은 그대로 남아야 한다(너무 많이 물러나지 않았는지).
		if len(got) < 300-utf8.UTFMax {
			t.Fatalf("길이가 %d바이트 — 룬 경계보다 더 물러났다", len(got))
		}
		if !strings.HasPrefix(split, got) {
			t.Fatalf("반환값이 입력의 접두사가 아니다: %q", got)
		}
	})

	t.Run("300바이트 이하는 그대로 돌려준다", func(t *testing.T) {
		cases := []string{
			"",
			"provider status 401: unauthorized",
			"제공자 오류: 인증에 실패했습니다",
			strings.Repeat("a", 300),
			"x" + strings.Repeat("한", 99) + "ab", // 정확히 300바이트
		}
		for _, in := range cases {
			if len(in) > 300 {
				t.Fatalf("시험 입력이 %d바이트 — 300 이하여야 한다", len(in))
			}
			if got := safeAIError(errors.New(in)); got != in {
				t.Fatalf("safeAIError(%q) = %q — 바뀌었다", in, got)
			}
		}
	})
}
}

// describeLastInteraction은 시각을 사람의 말로 바꾼다.
// 타임스탬프를 그대로 넘기면 AI가 날짜 계산을 틀리기 쉽다.
func describeLastInteraction(at *time.Time, now time.Time) string {
	days := DaysSince(at, now)
	switch {
	case days < 0:
		return "아직 기록 없음"
	case days == 0:
		return "오늘"
	case days < 30:
		return fmt.Sprintf("%d일 전", days)
	case days < 365:
		return fmt.Sprintf("약 %d개월 전", days/30)
	default:
		return fmt.Sprintf("약 %d년 전", days/365)
	}
}

// personConnections는 그 사람과 이어진 다른 사람들을 사람의 말로 돌려준다.
func (s *Server) personConnections(ctx context.Context, userID, personID string) ([]string, error) {
	rows, err := s.store.DB.Query(ctx, `SELECT p.display_name,l.kind FROM person_links l JOIN people p ON p.id = CASE WHEN l.person_a=$2 THEN l.person_b ELSE l.person_a END WHERE l.user_id=$1 AND $2 IN (l.person_a,l.person_b) ORDER BY l.strength DESC LIMIT 20`, userID, personID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := make([]string, 0)
	for rows.Next() {
		var name, kind string
		if err := rows.Scan(&name, &kind); err != nil {
			return nil, err
		}
		if label := linkKinds[kind]; label != "" {
			out = append(out, fmt.Sprintf("%s(%s)", name, label))
		} else {
			out = append(out, name)
		}
	}
	return out, rows.Err()
}

func (s *Server) proxyAIStream(ctx context.Context, w io.Writer, flusher http.Flusher, settings AISettings, prompt, relationshipContext string, maxTokens int) error {
	endpoint := strings.TrimRight(settings.BaseURL, "/")
	if !strings.HasSuffix(endpoint, "/responses") {
		if strings.HasSuffix(endpoint, "/v1") {
			endpoint += "/responses"
		} else {
			endpoint += "/v1/responses"
		}
	}
	parsed, err := url.Parse(endpoint)
	if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") {
		return errors.New("invalid AI endpoint")
	}
	body := map[string]any{"model": settings.Model, "instructions": settings.SystemPrompt, "input": relationshipContext + "\n\n사용자 질문:\n" + prompt, "max_output_tokens": maxTokens, "stream": true, "store": false}
	raw, _ := json.Marshal(body)
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(raw))
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "text/event-stream")
	if settings.APIKey != "" {
		req.Header.Set("Authorization", "Bearer "+settings.APIKey)
	}
	timeout := time.Duration(settings.RequestTimeoutSeconds) * time.Second
	if timeout < 5*time.Second {
		timeout = 120 * time.Second
	}
	transport := &http.Transport{Proxy: nil, DialContext: (&net.Dialer{Timeout: 10 * time.Second, KeepAlive: 30 * time.Second}).DialContext, ForceAttemptHTTP2: true, IdleConnTimeout: 90 * time.Second, TLSHandshakeTimeout: 10 * time.Second, ResponseHeaderTimeout: 30 * time.Second}
	client := &http.Client{Transport: transport, Timeout: timeout}
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		limited, _ := io.ReadAll(io.LimitReader(resp.Body, 8192))
		return fmt.Errorf("provider status %d: %s", resp.StatusCode, strings.TrimSpace(string(limited)))
	}
	scanner := bufio.NewScanner(resp.Body)
	scanner.Buffer(make([]byte, 64*1024), 4*1024*1024)
	event := ""
	dataLines := []string{}
	flushEvent := func() {
		if len(dataLines) == 0 {
			return
		}
		data := strings.Join(dataLines, "\n")
		dataLines = dataLines[:0]
		if data == "[DONE]" {
			return
		}
		var payload map[string]any
		if json.Unmarshal([]byte(data), &payload) != nil {
			return
		}
		delta := extractDelta(event, payload)
		if delta != "" {
			sendSSE(w, "delta", map[string]string{"text": delta})
			flusher.Flush()
		}
	}
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			flushEvent()
			event = ""
			continue
		}
		if strings.HasPrefix(line, "event:") {
			event = strings.TrimSpace(strings.TrimPrefix(line, "event:"))
		} else if strings.HasPrefix(line, "data:") {
			dataLines = append(dataLines, strings.TrimSpace(strings.TrimPrefix(line, "data:")))
		}
	}
	flushEvent()
	return scanner.Err()
}

func extractDelta(event string, payload map[string]any) string {
	if event == "response.output_text.delta" || payload["type"] == "response.output_text.delta" {
		if v, ok := payload["delta"].(string); ok {
			return v
		}
	}
	if choices, ok := payload["choices"].([]any); ok && len(choices) > 0 {
		if choice, ok := choices[0].(map[string]any); ok {
			if delta, ok := choice["delta"].(map[string]any); ok {
				if content, ok := delta["content"].(string); ok {
					return content
				}
			}
		}
	}
	return ""
}
func sendSSE(w io.Writer, event string, value any) {
	raw, _ := json.Marshal(value)
	_, _ = fmt.Fprintf(w, "event: %s\ndata: %s\n\n", event, raw)
}
func safeAIError(err error) string {
	message := err.Error()
	if len(message) <= 300 {
		return message
	}
	// 바이트로 그냥 자르면 멀티바이트 룬이 쪼개져 꼬리가 U+FFFD로 깨진다 —
	// 한국어 제공자 오류(룬 3바이트)에서는 300이 룬 경계와 어긋나기 쉽다.
	// 300번째 바이트가 룬의 중간(연속 바이트)이면 그 룬의 시작까지 물러난다.
	// 연속 바이트는 최대 3개라 이 되돌림은 길어지지 않는다.
	cut := 300
	for cut > 0 && !utf8.RuneStart(message[cut]) {
		cut--
	}
	return message[:cut]
}
